pub(crate) fn fc_store_box(mut ws: &mut crate::port::Cells, x0: i32, y0: i32, x1: i32, y1: i32) -> i32 {
    let at: i32 = crate::port::cells_at(ws, FT_BOXES);
    let mut p: i32 = 0;
    if at < BX_MAX {
        p = WS_BX + (at * BX_STRIDE);
        crate::port::cells_set(ws, p, x0);
        crate::port::cells_set(ws, p + 1, y0);
        crate::port::cells_set(ws, p + 2, x1);
        crate::port::cells_set(ws, p + 3, y1);
        crate::port::cells_set(ws, p + 4, 0);
        crate::port::cells_set(ws, p + 5, 0);
    }
    fc_inc(ws, FT_BOXES);
    return 0;
}
pub(crate) fn fc_wedge(mut ws: &mut crate::port::Cells, fill: i32) -> i32 {
    // A filled curve or polygon of some size: a candidate wedge of a pie; its colour is counted once.
    let n: i32 = crate::port::cells_at(ws, FT_NCOL);
    let mut j: i32 = 0;
    let mut dup: i32 = 0;
    fc_inc(ws, FT_WEDGE);
    while (j < n) && (j < 8) {
        if crate::port::cells_at(ws, FT_COLS + j) == fill {
            dup = 1;
        }
        j += 1;
    }
    if (dup == 0) && (n < 8) {
        crate::port::cells_set(ws, FT_COLS + n, fill);
        fc_inc(ws, FT_NCOL);
    }
    return 0;
}
pub(crate) fn fc_one_path(pa: &mut crate::port::Cells, i: i32, rx0: i32, ry0: i32, rx1: i32, ry1: i32, mut ws: &mut crate::port::Cells) -> i32 {
    // Path i of the region's page, visible and no clip, its centre in the region: its share of the features.
    let x0: i32 = pa_get(pa, i, pf_x0());
    let y0: i32 = pa_get(pa, i, pf_y0());
    let x1: i32 = pa_get(pa, i, pf_x1());
    let y1: i32 = pa_get(pa, i, pf_y1());
    let w: i32 = x1 - x0;
    let h: i32 = y1 - y0;
    let kind: i32 = pa_get(pa, i, pf_kind());
    let fl: i32 = pa_get(pa, i, pf_flags());
    let fill: i32 = pa_get(pa, i, pf_fill());
    let stroke: i32 = pa_get(pa, i, pf_stroke());
    let rw: i32 = rx1 - rx0;
    let rh: i32 = ry1 - ry0;
    let cx: i32 = (x0 + x1) / 2;
    let cy: i32 = (y0 + y1) / 2;
    let mut filled: i32 = 0;
    let mut stroked: i32 = 0;
    let mut rule: i32 = 0;
    let mut span: i32 = 0;
    let mut j: i32 = 0;
    let mut at: i32 = 0;
    let mut p: i32 = 0;
    if (fl & pg_filled()) != 0 {
        filled = 1;
    }
    if (fl & pg_stroked()) != 0 {
        stroked = 1;
    }
    fc_inc(ws, FT_NP);
    if (filled == 1) && (fc_chroma(fill) >= 48) {
        fc_inc(ws, FT_COLOR);
    } else if (stroked == 1) && (fc_chroma(stroke) >= 48) {
        fc_inc(ws, FT_COLOR);
    }
    if (fl & (pg_shading() | pg_pattern())) != 0 {
        fc_inc(ws, FT_SHADE);
    }
    if kind == pa_line() {
        if (h <= 300) && (w > h) {
            rule = 1;
        } else if (w <= 300) && (h > w) {
            rule = 2;
        } else {
            rule = 3;
        }
    }
    if kind == pa_rect() {
        if (fc_min(w, h) <= 200) && (fc_max(w, h) >= 500) {
            if h <= w {
                rule = 1;
            } else {
                rule = 2;
            }
        }
    }
    if rule == 1 {
        span = w;
        if (span >= 3000) && ((span * 100) >= (rw * 45)) {
            fc_inc(ws, FT_NHL);
            if span > crate::port::cells_at(ws, FT_HLEN) {
                crate::port::cells_set(ws, FT_HLEN, span);
                crate::port::cells_set(ws, FT_HX0, x0);
                crate::port::cells_set(ws, FT_HX1, x1);
                crate::port::cells_set(ws, FT_HY, cy);
            }
        }
        if span >= 800 {
            fc_inc(ws, FT_CONN);
        }
    }
    if rule == 2 {
        span = h;
        if (span >= 2500) && ((span * 100) >= (rh * 40)) {
            fc_inc(ws, FT_NVL);
            if span > crate::port::cells_at(ws, FT_VLEN) {
                crate::port::cells_set(ws, FT_VLEN, span);
                crate::port::cells_set(ws, FT_VX, cx);
                crate::port::cells_set(ws, FT_VY0, y0);
                crate::port::cells_set(ws, FT_VY1, y1);
            }
        }
        if span >= 800 {
            fc_inc(ws, FT_CONN);
        }
    }
    if rule == 3 {
        fc_inc(ws, FT_SLANT);
    }
    // a thin tall filled bar (a barcode's), which is also a vertical rule when it is under 2 pt wide
    if (kind == pa_rect()) && ((filled == 1) && ((w <= 400) && (h >= 1500))) {
        fc_inc(ws, FT_THIN);
        if crate::port::cells_at(ws, FT_THIN) == 1 {
            crate::port::cells_set(ws, FT_TOPY, y0);
            crate::port::cells_set(ws, FT_BOTY, y1);
            crate::port::cells_set(ws, FT_ALIGNED, 1);
        } else if (fc_near_eq(y0, crate::port::cells_at(ws, FT_TOPY), 150) == 1) && (fc_near_eq(y1, crate::port::cells_at(ws, FT_BOTY), 150) == 1) {
            fc_inc(ws, FT_ALIGNED);
        }
    }
    if (rule == 0) && (kind == pa_rect()) {
        fc_inc(ws, FT_RECT);
        if (filled == 1) && ((fill >= 0) && ((fill != 16777215) && ((w >= 300) && (h >= 300)))) {
            at = crate::port::cells_at(ws, FT_NBAR);
            if at < BR_MAX {
                p = WS_BR + (at * BR_STRIDE);
                crate::port::cells_set(ws, p, x0);
                crate::port::cells_set(ws, p + 1, y0);
                crate::port::cells_set(ws, p + 2, x1);
                crate::port::cells_set(ws, p + 3, y1);
            }
            fc_inc(ws, FT_NBAR);
        }
        if (filled == 1) && ((w >= 400) && ((w <= 1400) && ((h >= 400) && ((h <= 1400) && (fc_abs(w - h) <= 300))))) {
            at = crate::port::cells_at(ws, FT_NSW);
            if at < SW_MAX {
                p = WS_SW + (at * SW_STRIDE);
                crate::port::cells_set(ws, p, x0);
                crate::port::cells_set(ws, p + 1, y0);
                crate::port::cells_set(ws, p + 2, x1);
                crate::port::cells_set(ws, p + 3, y1);
                crate::port::cells_set(ws, p + 4, 0);
            }
            fc_inc(ws, FT_NSW);
        }
        if (filled == 1) && ((w <= 700) && (h <= 700)) {
            fc_inc(ws, FT_TINY);
        }
        if ((stroked == 1) || ((filled == 1) && (fill >= 0))) && ((w >= 1800) && (h >= 1000)) {
            fc_store_box(ws, x0, y0, x1, y1);
        }
        if ((stroked == 1) || ((filled == 1) && ((fill >= 0) && (fill != 16777215)))) && (fc_ge(fc_area(x0, y0, x1, y1), fc_area(rx0, ry0, rx1, ry1), 850) == 1) {
            fc_inc(ws, FT_FRAME);
        }
    }
    if kind == pa_curve() {
        fc_inc(ws, FT_CURVE);
        if (filled == 1) && ((w >= 1500) && (h >= 1500)) {
            fc_wedge(ws, fill);
        }
        if (stroked == 1) && ((filled == 0) && (((fl & pg_closed()) != 0) && ((w >= 2000) && ((fc_abs(w - h) * 8) <= w)))) {
            at = crate::port::cells_at(ws, FT_NRG);
            j = 0;
            while (j < at) && (j < RG_MAX) {
                p = FT_RINGS + (j * 3);
                if (fc_abs(cx - crate::port::cells_at(ws, p)) <= 300) && ((fc_abs(cy - crate::port::cells_at(ws, p + 1)) <= 300) && (fc_abs(w - crate::port::cells_at(ws, p + 2)) >= 500)) {
                    fc_inc(ws, FT_RING);
                }
                j += 1;
            }
            if at < RG_MAX {
                p = FT_RINGS + (at * 3);
                crate::port::cells_set(ws, p, cx);
                crate::port::cells_set(ws, p + 1, cy);
                crate::port::cells_set(ws, p + 2, w);
            }
            fc_inc(ws, FT_NRG);
        }
        if (stroked == 1) && ((filled == 0) && (((fl & pg_closed()) == 0) && ((w * 100) >= (rw * 30)))) {
            fc_inc(ws, FT_SERIES);
        }
        if ((stroked == 1) || (filled == 1)) && ((w >= 1800) && (h >= 1000)) {
            fc_store_box(ws, x0, y0, x1, y1);
        }
    }
    if kind == pa_other() {
        fc_inc(ws, FT_OTHER);
        if (filled == 1) && ((w <= 1600) && (h <= 1600)) {
            fc_inc(ws, FT_ARROW);
            fc_inc(ws, FT_CONN);
        } else if (filled == 1) && ((w >= 1500) && (h >= 1500)) {
            fc_wedge(ws, fill);
        }
        if (stroked == 1) && ((filled == 0) && ((w * 100) >= (rw * 30))) {
            fc_inc(ws, FT_SERIES);
        }
    }
    return 0;
}
pub(crate) fn fc_axes(mut ws: &mut crate::port::Cells) -> i32 {
    // The longest horizontal and the longest vertical rule are AXES when they meet (each grown by 5 pt).
    if (crate::port::cells_at(ws, FT_NHL) >= 1) && (crate::port::cells_at(ws, FT_NVL) >= 1) {
        if ((crate::port::cells_at(ws, FT_VX) + 500) >= crate::port::cells_at(ws, FT_HX0)) && (((crate::port::cells_at(ws, FT_VX) - 500) <= crate::port::cells_at(ws, FT_HX1)) && (((crate::port::cells_at(ws, FT_HY) + 500) >= crate::port::cells_at(ws, FT_VY0)) && ((crate::port::cells_at(ws, FT_HY) - 500) <= crate::port::cells_at(ws, FT_VY1)))) {
            crate::port::cells_set(ws, FT_AXES, 1);
        }
    }
    return 0;
}
pub(crate) fn fc_ticks(pa: &mut crate::port::Cells, page: i32, rx0: i32, ry0: i32, rx1: i32, ry1: i32, mut ws: &mut crate::port::Cells) -> i32 {
    // Short rules (1.5 to 11 pt) that cross or touch an axis, along it: its ticks.
    let n: i32 = crate::port::cells_len(pa) / 24;
    let mut i: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut kind: i32 = 0;
    while i < n {
        if (pa_get(pa, i, pf_page()) == page) && ((pa_get(pa, i, pf_vis()) == 0) && ((pa_get(pa, i, pf_flags()) & pg_clip()) == 0)) {
            kind = pa_get(pa, i, pf_kind());
            x0 = pa_get(pa, i, pf_x0());
            y0 = pa_get(pa, i, pf_y0());
            x1 = pa_get(pa, i, pf_x1());
            y1 = pa_get(pa, i, pf_y1());
            if ((kind == pa_line()) || (kind == pa_rect())) && ((x0 >= (rx0 - 100)) && ((x1 <= (rx1 + 100)) && ((y0 >= (ry0 - 100)) && (y1 <= (ry1 + 100))))) {
                if ((y1 - y0) <= 300) && (((x1 - x0) >= 150) && ((x1 - x0) <= 1100)) {
                    if (x0 <= (crate::port::cells_at(ws, FT_VX) + 300)) && ((x1 >= (crate::port::cells_at(ws, FT_VX) - 300)) && ((y0 >= (crate::port::cells_at(ws, FT_VY0) - 200)) && (y1 <= (crate::port::cells_at(ws, FT_VY1) + 200)))) {
                        fc_inc(ws, FT_TICKS);
                    }
                }
                if ((x1 - x0) <= 300) && (((y1 - y0) >= 150) && ((y1 - y0) <= 1100)) {
                    if (y0 <= (crate::port::cells_at(ws, FT_HY) + 300)) && ((y1 >= (crate::port::cells_at(ws, FT_HY) - 300)) && ((x0 >= (crate::port::cells_at(ws, FT_HX0) - 200)) && (x1 <= (crate::port::cells_at(ws, FT_HX1) + 200)))) {
                        fc_inc(ws, FT_TICKS);
                    }
                }
            }
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn fc_bar_run(mut ws: &mut crate::port::Cells, dir: i32) -> i32 {
    // The largest group of bars on one baseline (dir 0: the same bottom) or one left edge (dir 1), and whether they differ in length.
    let n: i32 = fc_min(crate::port::cells_at(ws, FT_NBAR), BR_MAX);
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut c: i32 = 0;
    let mut vr: i32 = 0;
    let mut pi: i32 = 0;
    let mut pj: i32 = 0;
    let mut ki: i32 = 0;
    let mut kj: i32 = 0;
    let mut li: i32 = 0;
    let mut lj: i32 = 0;
    while i < n {
        pi = WS_BR + (i * BR_STRIDE);
        c = 0;
        vr = 0;
        if dir == 0 {
            ki = crate::port::cells_at(ws, pi + 3);
            li = crate::port::cells_at(ws, pi + 3) - crate::port::cells_at(ws, pi + 1);
        } else {
            ki = crate::port::cells_at(ws, pi);
            li = crate::port::cells_at(ws, pi + 2) - crate::port::cells_at(ws, pi);
        }
        j = 0;
        while j < n {
            pj = WS_BR + (j * BR_STRIDE);
            if dir == 0 {
                kj = crate::port::cells_at(ws, pj + 3);
                lj = crate::port::cells_at(ws, pj + 3) - crate::port::cells_at(ws, pj + 1);
            } else {
                kj = crate::port::cells_at(ws, pj);
                lj = crate::port::cells_at(ws, pj + 2) - crate::port::cells_at(ws, pj);
            }
            if fc_abs(ki - kj) <= 150 {
                c += 1;
                if fc_abs(li - lj) > 150 {
                    vr = 1;
                }
            }
            j += 1;
        }
        if c > crate::port::cells_at(ws, FT_BARS) {
            crate::port::cells_set(ws, FT_BARS, c);
            crate::port::cells_set(ws, FT_BARVAR, vr);
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn fc_words(fw: &mut crate::port::Cells, et: &mut crate::port::Cells, page: i32, rx0: i32, ry0: i32, rx1: i32, ry1: i32, mut ws: &mut crate::port::Cells) -> i32 {
    // The words in the region and within `FC_ZONE` of it: how many, how many are numbers, how many lie in it; the words inside each
    // box; the small squares with a word at their right.
    let n: i32 = wd_count(fw);
    let mut i: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut cx: i32 = 0;
    let mut cy: i32 = 0;
    let mut k: i32 = 0;
    let mut p: i32 = 0;
    let nb: i32 = fc_min(crate::port::cells_at(ws, FT_BOXES), BX_MAX);
    let ns: i32 = fc_min(crate::port::cells_at(ws, FT_NSW), SW_MAX);
    while i < n {
        if wd_get(fw, i, hd_page()) == page {
            x0 = wd_get(fw, i, hd_x0());
            y0 = wd_get(fw, i, hd_y0());
            x1 = wd_get(fw, i, hd_x1());
            y1 = wd_get(fw, i, hd_y1());
            cx = (x0 + x1) / 2;
            cy = (y0 + y1) / 2;
            if (cx >= (rx0 - FC_ZONE)) && ((cx <= (rx1 + FC_ZONE)) && ((cy >= (ry0 - FC_ZONE)) && (cy <= (ry1 + FC_ZONE)))) {
                fc_inc(ws, FT_WORDS);
                if fc_numeric(et, wd_get(fw, i, hd_tstart()), wd_get(fw, i, hd_tlen())) == 1 {
                    fc_inc(ws, FT_NUM);
                }
                if (cx >= rx0) && ((cx <= rx1) && ((cy >= ry0) && (cy <= ry1))) {
                    fc_inc(ws, FT_INSIDE);
                }
                k = 0;
                while k < nb {
                    p = WS_BX + (k * BX_STRIDE);
                    if (x0 >= (crate::port::cells_at(ws, p) - 100)) && ((x1 <= (crate::port::cells_at(ws, p + 2) + 100)) && ((y0 >= (crate::port::cells_at(ws, p + 1) - 100)) && (y1 <= (crate::port::cells_at(ws, p + 3) + 100)))) {
                        crate::port::cells_set(ws, p + 4, crate::port::cells_at(ws, p + 4) + 1);
                    }
                    k += 1;
                }
                k = 0;
                while k < ns {
                    p = WS_SW + (k * SW_STRIDE);
                    if (x0 >= (crate::port::cells_at(ws, p + 2) - 100)) && ((x0 <= (crate::port::cells_at(ws, p + 2) + 1500)) && (fc_abs(cy - ((crate::port::cells_at(ws, p + 1) + crate::port::cells_at(ws, p + 3)) / 2)) <= 600)) {
                        crate::port::cells_set(ws, p + 4, 1);
                    }
                    k += 1;
                }
            }
        }
        i += 1;
    }
    k = 0;
    while k < nb {
        p = WS_BX + (k * BX_STRIDE);
        if (crate::port::cells_at(ws, p + 4) > 0) && (fc_ge(fc_area(crate::port::cells_at(ws, p), crate::port::cells_at(ws, p + 1), crate::port::cells_at(ws, p + 2), crate::port::cells_at(ws, p + 3)), fc_area(rx0, ry0, rx1, ry1), 850) == 0) {
            fc_inc(ws, FT_BOXW);
        }
        k += 1;
    }
    k = 0;
    while k < ns {
        if crate::port::cells_at(ws, (WS_SW + (k * SW_STRIDE)) + 4) == 1 {
            fc_inc(ws, FT_SWATCH);
        }
        k += 1;
    }
    return n;
}
pub(crate) fn fc_lines(fl: &mut crate::port::Cells, page: i32, rx0: i32, ry0: i32, rx1: i32, ry1: i32, mut ws: &mut crate::port::Cells) -> i32 {
    // Lines of five words or more whose centre is in the region: prose. A region with some is a text box, a sidebar or a background.
    let n: i32 = ln_count(fl);
    let mut i: i32 = 0;
    let mut cx: i32 = 0;
    let mut cy: i32 = 0;
    while i < n {
        if (ln_get(fl, i, lh_page()) == page) && (ln_get(fl, i, lh_count()) >= 5) {
            cx = (ln_get(fl, i, lh_x0()) + ln_get(fl, i, lh_x1())) / 2;
            cy = (ln_get(fl, i, lh_y0()) + ln_get(fl, i, lh_y1())) / 2;
            if (cx >= rx0) && ((cx <= rx1) && ((cy >= ry0) && (cy <= ry1))) {
                fc_inc(ws, FT_PROSE);
            }
        }
        i += 1;
    }
    return n;
}
pub fn fc_measure(pa: &mut crate::port::Cells, grl: &mut crate::port::Cells, fw: &mut crate::port::Cells, fl: &mut crate::port::Cells, et: &mut crate::port::Cells, page: i32, rx0: i32, ry0: i32, rx1: i32, ry1: i32, mut ws: &mut crate::port::Cells) -> i32 {
    // Measure the region: `ft`'s slots of `ws`, the boxes, the small squares and the bars. Answers 0, or 1 when the document's
    // budget of rows (`FC_WORK`) is spent and the region was left unmeasured.
    let work: i32 = crate::port::cells_at(ws, FT_WORK);
    let n: i32 = crate::port::cells_len(pa) / 24;
    let ng: i32 = grl_count(grl);
    let rw: i32 = rx1 - rx0;
    let rh: i32 = ry1 - ry0;
    let mut i: i32 = 0;
    let mut cx: i32 = 0;
    let mut cy: i32 = 0;
    let mut span: i32 = 0;
    while i < WS_SIZE {
        crate::port::cells_set(ws, i, 0);
        i += 1;
    }
    crate::port::cells_set(ws, FT_WORK, work);
    if work > FC_WORK {
        return 1;
    }
    crate::port::cells_set(ws, FT_WORK, work + (n + (ng + (wd_count(fw) + ln_count(fl)))));
    i = 0;
    while i < n {
        if (pa_get(pa, i, pf_page()) == page) && ((pa_get(pa, i, pf_vis()) == 0) && ((pa_get(pa, i, pf_flags()) & pg_clip()) == 0)) {
            cx = (pa_get(pa, i, pf_x0()) + pa_get(pa, i, pf_x1())) / 2;
            cy = (pa_get(pa, i, pf_y0()) + pa_get(pa, i, pf_y1())) / 2;
            if (cx >= (rx0 - 100)) && ((cx <= (rx1 + 100)) && ((cy >= (ry0 - 100)) && (cy <= (ry1 + 100)))) {
                fc_one_path(pa, i, rx0, ry0, rx1, ry1, ws);
            }
        }
        i += 1;
    }
    if crate::port::cells_at(ws, FT_NP) == 0 {
        i = 0;
        while i < ng {
            if grl_get(grl, i, 0) == page {
                cx = (grl_get(grl, i, 1) + grl_get(grl, i, 3)) / 2;
                cy = (grl_get(grl, i, 2) + grl_get(grl, i, 4)) / 2;
                if (cx >= rx0) && ((cx <= rx1) && ((cy >= ry0) && (cy <= ry1))) {
                    if grl_get(grl, i, 10) == go_h() {
                        span = grl_get(grl, i, 3) - grl_get(grl, i, 1);
                        if (span >= 3000) && ((span * 100) >= (rw * 45)) {
                            fc_inc(ws, FT_NHL);
                            if span > crate::port::cells_at(ws, FT_HLEN) {
                                crate::port::cells_set(ws, FT_HLEN, span);
                                crate::port::cells_set(ws, FT_HX0, grl_get(grl, i, 1));
                                crate::port::cells_set(ws, FT_HX1, grl_get(grl, i, 3));
                                crate::port::cells_set(ws, FT_HY, cy);
                            }
                        }
                    }
                    if grl_get(grl, i, 10) == go_v() {
                        span = grl_get(grl, i, 4) - grl_get(grl, i, 2);
                        if (span >= 2500) && ((span * 100) >= (rh * 40)) {
                            fc_inc(ws, FT_NVL);
                            if span > crate::port::cells_at(ws, FT_VLEN) {
                                crate::port::cells_set(ws, FT_VLEN, span);
                                crate::port::cells_set(ws, FT_VX, cx);
                                crate::port::cells_set(ws, FT_VY0, grl_get(grl, i, 2));
                                crate::port::cells_set(ws, FT_VY1, grl_get(grl, i, 4));
                            }
                        }
                    }
                }
            }
            i += 1;
        }
    }
    fc_axes(ws);
    if crate::port::cells_at(ws, FT_AXES) == 1 {
        fc_ticks(pa, page, rx0, ry0, rx1, ry1, ws);
    }
    fc_bar_run(ws, 0);
    fc_bar_run(ws, 1);
    fc_words(fw, et, page, rx0, ry0, rx1, ry1, ws);
    fc_lines(fl, page, rx0, ry0, rx1, ry1, ws);
    return 0;
}
pub(crate) fn fc_pack(kind: i32, conf: i32) -> i32 {
    return (kind * 1024) + conf;
}
pub fn fc_recur(cand: &mut crate::port::Cells, row: i32) -> i32 {
    // THE HOOK of P8.4 (logos and their recurrence across pages): how much the same drawing at the same place on other pages should
    // raise the confidence of a logo (per mille) for the region `row` of `cand`. P8.1 does not measure recurrence: 0.
    return 0;
}
pub(crate) fn fc_in_band(y0: i32, y1: i32, pageh: i32) -> i32 {
    // 1 when the region lies in the header band (the top fifth of the page) or the footer band.
    if (pageh > 0) && (((y1 / 10) * 1000) <= ((pageh / 10) * FC_BAND)) {
        return 1;
    }
    if (pageh > 0) && (((y0 / 10) * 1000) >= ((pageh / 10) * (1000 - FC_BAND))) {
        return 1;
    }
    return 0;
}
pub fn fc_vector_kind(ws: &mut crate::port::Cells, rx0: i32, ry0: i32, rx1: i32, ry1: i32, pageh: i32, recur: i32) -> i32 {
    // The kind and confidence of a region from its measured features: `fc-pack`ed. 0 kind is none (see `fc-judge`).
    let rw: i32 = rx1 - rx0;
    let rh: i32 = ry1 - ry0;
    let np: i32 = crate::port::cells_at(ws, FT_NP);
    let axes: i32 = crate::port::cells_at(ws, FT_AXES);
    let bars: i32 = crate::port::cells_at(ws, FT_BARS);
    let ticks: i32 = crate::port::cells_at(ws, FT_TICKS);
    let series: i32 = crate::port::cells_at(ws, FT_SERIES);
    let slant: i32 = crate::port::cells_at(ws, FT_SLANT);
    let num: i32 = crate::port::cells_at(ws, FT_NUM);
    let mut conf: i32 = 0;
    if (axes == 1) && ((bars >= 2) || ((series >= 1) || ((slant >= 2) || ((ticks >= 2) || (num >= 2))))) {
        conf = 640;
        if ticks >= 3 {
            conf += 40;
        }
        if (bars >= 2) || ((series >= 1) || (slant >= 2)) {
            conf += 40;
        }
        if num >= 2 {
            conf += 40;
        }
        return fc_pack(fg_chart(), conf);
    }
    if (crate::port::cells_at(ws, FT_THIN) >= 12) && ((crate::port::cells_at(ws, FT_ALIGNED) * 10) >= (crate::port::cells_at(ws, FT_THIN) * 8)) {
        return fc_pack(fg_barcode(), 700);
    }
    if (crate::port::cells_at(ws, FT_TINY) >= 40) && (((rw * 10) <= (rh * 14)) && ((rh * 10) <= (rw * 14))) {
        return fc_pack(fg_qr(), 700);
    }
    if (crate::port::cells_at(ws, FT_NCOL) >= 3) && ((crate::port::cells_at(ws, FT_WEDGE) >= 3) && (((rw * 10) <= (rh * 17)) && ((rh * 10) <= (rw * 17)))) {
        conf = 560;
        if crate::port::cells_at(ws, FT_SWATCH) >= 2 {
            conf = 620;
        }
        return fc_pack(fg_chart(), conf);
    }
    if (bars >= 3) && (crate::port::cells_at(ws, FT_BARVAR) == 1) {
        return fc_pack(fg_chart(), 560);
    }
    if (axes == 1) && ((crate::port::cells_at(ws, FT_NHL) + crate::port::cells_at(ws, FT_NVL)) >= 2) {
        return fc_pack(fg_chart(), 520);
    }
    if (axes == 0) && ((crate::port::cells_at(ws, FT_BOXW) >= 2) && (crate::port::cells_at(ws, FT_CONN) >= 1)) {
        conf = 600;
        if crate::port::cells_at(ws, FT_BOXW) >= 3 {
            conf += 50;
        }
        if crate::port::cells_at(ws, FT_ARROW) >= 1 {
            conf += 50;
        }
        return fc_pack(fg_diagram(), conf);
    }
    if (fc_max(rw, rh) <= FC_SMALL) && ((np <= 24) && ((crate::port::cells_at(ws, FT_PROSE) == 0) && ((fc_in_band(ry0, ry1, pageh) == 1) || (recur > 0)))) {
        conf = 480 + recur;
        if crate::port::cells_at(ws, FT_COLOR) >= 1 {
            conf += 60;
        }
        if (crate::port::cells_at(ws, FT_WORDS) >= 1) && (crate::port::cells_at(ws, FT_WORDS) <= 3) {
            conf += 40;
        }
        return fc_pack(fg_logo(), fc_min(conf, 1000));
    }
    if (crate::port::cells_at(ws, FT_SHADE) >= 1) && ((np <= 3) && (crate::port::cells_at(ws, FT_INSIDE) == 0)) {
        return fc_pack(fg_photo(), 520);
    }
    if (crate::port::cells_at(ws, FT_FRAME) >= 1) && ((rw >= 15000) && ((rh >= 8000) && ((crate::port::cells_at(ws, FT_INSIDE) >= 1) && (crate::port::cells_at(ws, FT_INSIDE) <= 8)))) {
        return fc_pack(fg_screenshot(), 520);
    }
    if (np >= 60) && ((((crate::port::cells_at(ws, FT_CURVE) + crate::port::cells_at(ws, FT_OTHER)) * 2) >= np) && ((crate::port::cells_at(ws, FT_WORDS) >= 6) && ((rw >= 20000) && (rh >= 15000)))) {
        return fc_pack(fg_map(), 540);
    }
    if (np >= 8) && (((crate::port::cells_at(ws, FT_CURVE) + crate::port::cells_at(ws, FT_OTHER)) * 2) >= np) {
        return fc_pack(fg_illustration(), 520);
    }
    return fc_pack(fg_unknown(), 300);
}
pub fn fc_image_kind(fi: &mut crate::port::Cells, imx: i32, rw: i32, rh: i32, ry0: i32, ry1: i32, pageh: i32, recur: i32) -> i32 {
    // The kind and confidence of an image placement (row `imx` of `im`, its dictionary's row in `fi`), `fc-pack`ed: a raster that
    // needed many bits a pixel is a photograph, a flat two-colour one a code, a small flat one at the head or foot of the page a logo.
    let b: i32 = imx * FI_STRIDE;
    let mut conf: i32 = 0;
    if (imx < 0) || (crate::port::cells_len(fi) < (b + FI_STRIDE)) {
        return fc_pack(fg_unknown(), 300);
    }
    if crate::port::cells_at(fi, b) == 0 {
        return fc_pack(fg_unknown(), 300);
    }
    if (crate::port::cells_at(fi, b + 4) == 1) || ((crate::port::cells_at(fi, b + 2) == 0) || ((crate::port::cells_at(fi, b + 1) == 9) || (crate::port::cells_at(fi, b + 1) == 10))) {
        if ((rw * 10) >= (rh * 22)) && (rh <= 9000) {
            return fc_pack(fg_barcode(), 540);
        }
        if ((rw * 100) >= (rh * 80)) && (((rw * 100) <= (rh * 125)) && (fc_max(rw, rh) <= 20000)) {
            return fc_pack(fg_qr(), 540);
        }
        return fc_pack(fg_illustration(), 520);
    }
    if crate::port::cells_at(fi, b + 7) >= FC_PHOTO_BPP {
        conf = 560 + fc_min(240, (crate::port::cells_at(fi, b + 7) - FC_PHOTO_BPP) / 2);
        return fc_pack(fg_photo(), conf);
    }
    if (fc_max(rw, rh) <= FC_SMALL) && ((fc_in_band(ry0, ry1, pageh) == 1) || ((crate::port::cells_at(fi, b + 9) >= 1) || (recur > 0))) {
        return fc_pack(fg_logo(), fc_min(1000, 580 + recur));
    }
    if (rw >= 20000) && (rh >= 12000) {
        return fc_pack(fg_screenshot(), 450);
    }
    return fc_pack(fg_unknown(), 300);
}
pub fn fc_reject(ws: &mut crate::port::Cells) -> i32 {
    // 1 when the measured region is no figure: covered with prose, a seal (rings one in another) or a lattice of rules with no axes.
    if crate::port::cells_at(ws, FT_PROSE) >= 2 {
        return 1;
    }
    if crate::port::cells_at(ws, FT_RING) >= 1 {
        return 1;
    }
    if (crate::port::cells_at(ws, FT_AXES) == 0) && ((crate::port::cells_at(ws, FT_NHL) >= 3) && (crate::port::cells_at(ws, FT_NVL) >= 3)) {
        return 1;
    }
    return 0;
}
pub(crate) fn fc_taken(fcand: &mut crate::port::Cells, row: i32, page: i32, cx0: i32, cx1: i32, cy0: i32) -> i32 {
    // 1 when another candidate region of the page lies just above the caption (box cx0..cx1 x, top cy0): the caption is its, not the
    // region's below it (a figure's caption is under it).
    let n: i32 = crate::port::cells_len(fcand) / CR_STRIDE;
    let mut r: i32 = 0;
    let mut b: i32 = 0;
    while r < n {
        b = r * CR_STRIDE;
        if (r != row) && ((crate::port::cells_at(fcand, b + CR_PAGE) == page) && ((fc_min(cx1, crate::port::cells_at(fcand, b + (CR_VX + 2))) > fc_max(cx0, crate::port::cells_at(fcand, b + CR_VX))) && (((cy0 - crate::port::cells_at(fcand, b + (CR_VX + 3))) >= -200) && ((cy0 - crate::port::cells_at(fcand, b + (CR_VX + 3))) <= FC_CAPGAP)))) {
            return 1;
        }
        r += 1;
    }
    return 0;
}
pub(crate) fn fc_captioned(nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, fcand: &mut crate::port::Cells, row: i32, page: i32, x0: i32, y0: i32, x1: i32, y1: i32) -> i32 {
    // 1 when a figure's caption (a `caption` the notes stage made of a `Figure` label) lies within `FC_CAPGAP` below the box, or above it when
    // no other region lies above that caption (`fc-taken`).
    let nn: i32 = node_count(nodes);
    let mut n: i32 = 0;
    let mut r: i32 = 0;
    while n < nn {
        if (node_kind(nodes, n) == nk_caption()) && (node_aux(nodes, n) == 1) {
            r = node_region_head(nodes, n);
            if (r >= 0) && ((region_page(regions, r) == page) && (fc_min(x1, region_x1(regions, r)) > fc_max(x0, region_x0(regions, r)))) {
                if ((region_y0(regions, r) - y1) >= -200) && ((region_y0(regions, r) - y1) <= FC_CAPGAP) {
                    return 1;
                }
                if ((y0 - region_y1(regions, r)) >= -200) && ((y0 - region_y1(regions, r)) <= FC_CAPGAP) {
                    if fc_taken(fcand, row, page, region_x0(regions, r), region_x1(regions, r), region_y0(regions, r)) == 0 {
                        return 1;
                    }
                }
            }
        }
        n += 1;
    }
    return 0;
}
pub(crate) fn fc_link(cand: &mut crate::port::Cells, page: i32, x0: i32, y0: i32, x1: i32, y1: i32) -> i32 {
    // The asset stage's candidate row (an image's) with this placement box on this page, or -1.
    let n: i32 = crate::port::cells_len(cand) / CR_STRIDE;
    let mut r: i32 = 0;
    let mut b: i32 = 0;
    while r < n {
        b = r * CR_STRIDE;
        if (crate::port::cells_at(cand, b + CR_PAGE) == page) && ((crate::port::cells_at(cand, b + CR_KORI) >= -1) && ((crate::port::cells_at(cand, b + CR_BX) == x0) && ((crate::port::cells_at(cand, b + (CR_BX + 1)) == y0) && ((crate::port::cells_at(cand, b + (CR_BX + 2)) == x1) && (crate::port::cells_at(cand, b + (CR_BX + 3)) == y1))))) {
            return r;
        }
        r += 1;
    }
    return -1;
}
pub fn fc_stage(nodes: &mut crate::port::Cells, attrs: &mut crate::port::Cells, regions: &mut crate::port::Cells, text: &mut crate::port::Cells, pages: &mut crate::port::Cells, mut fnodes: &mut crate::port::Cells, mut fattrs: &mut crate::port::Cells, mut fregions: &mut crate::port::Cells, mut fnm: &mut crate::port::Cells, pa: &mut crate::port::Cells, im: &mut crate::port::Cells, fi: &mut crate::port::Cells, grg: &mut crate::port::Cells, grl: &mut crate::port::Cells, fw: &mut crate::port::Cells, fl: &mut crate::port::Cells, et: &mut crate::port::Cells, pg: &mut crate::port::Cells, mut cand: &mut crate::port::Cells, level: i32, mut fcand: &mut crate::port::Cells, mut cl: &mut crate::port::Cells, mut fg: &mut crate::port::Cells, mut fd: &mut crate::port::Cells, mut ab: &mut crate::port::Cells, mut ws: &mut crate::port::Cells) -> i32 {
    // THE FIGURES (SPEC 10.6): the candidate regions (the image placements, the vector clusters of `emon.asset`, the shaded fills, P7.G's
    // `figure` regions), each measured and judged, the ones that are figures placed among the blocks with their kind, confidence
    // and `labels` (`rs-figures`) into the empty arenas `fnodes fattrs fregions` (the caller swaps them in, then restructures). `cand`
    // is the asset stage's own candidate rows (empty when `assets` is off; `level` is that setting): an image figure learns its row,
    // and at `figures` a region of ours the asset stage did not find is added to it (`as-region-add`). Scratch: `fnm fcand cl fg fd ab ws`.
    // Answers the number of figures.
    let mut nr: i32 = 0;
    let mut i: i32 = 0;
    let mut row: i32 = 0;
    let mut b: i32 = 0;
    let mut page: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut pk: i32 = 0;
    let mut kind: i32 = 0;
    let mut conf: i32 = 0;
    let mut capt: i32 = 0;
    let mut rej: i32 = 0;
    let mut out: i32 = 1;
    let mut measured: i32 = 0;
    let mut pageh: i32 = 0;
    let mut recur: i32 = 0;
    let mut srcs: i32 = 0;
    let mut link: i32 = 0;
    let mut k: i32 = 0;
    crate::port::cells_drop(fcand, 0);
    crate::port::cells_drop(fd, 0);
    crate::port::cells_drop(ws, 0);
    while i < WS_SIZE {
        crate::port::cells_push(ws, 0);
        i += 1;
    }
    fc_image_rows(im, pa, pg, fcand);
    as_vector_regions(pa, pg, fcand, cl);
    fc_shading_regions(pa, pages, fcand);
    fc_grg_regions(grg, pages, fcand);
    as_figure_rows(fcand, pages, nodes, regions, 2, fg);
    nr = as_count(fcand);
    i = 0;
    while i < (nr * FD_STRIDE) {
        crate::port::cells_push(fd, 0);
        i += 1;
    }
    i = 0;
    while i < nr {
        crate::port::cells_set(fd, (i * FD_STRIDE) + 3, -1);
        crate::port::cells_set(fd, (i * FD_STRIDE) + 4, -1);
        i += 1;
    }
    i = 1;
    while i < crate::port::cells_len(fg) {
        row = crate::port::cells_at(fg, i);
        b = row * CR_STRIDE;
        page = crate::port::cells_at(fcand, b + CR_PAGE);
        x0 = crate::port::cells_at(fcand, b + CR_VX);
        y0 = crate::port::cells_at(fcand, b + (CR_VX + 1));
        x1 = crate::port::cells_at(fcand, b + (CR_VX + 2));
        y1 = crate::port::cells_at(fcand, b + (CR_VX + 3));
        pageh = page_h(pages, page - 1);
        recur = fc_recur(fcand, row);
        rej = 1;
        if measured < FC_MAXREG {
            measured += 1;
            rej = 0;
            if fc_measure(pa, grl, fw, fl, et, page, x0, y0, x1, y1, ws) == 0 {
                rej = fc_reject(ws);
            }
        }
        if crate::port::cells_at(fcand, b + CR_KORI) == -1 {
            pk = fc_image_kind(fi, crate::port::cells_at(fcand, b + CR_ROW), x1 - x0, y1 - y0, y0, y1, pageh, recur);
        } else {
            pk = fc_vector_kind(ws, x0, y0, x1, y1, pageh, recur);
        }
        kind = pk / 1024;
        conf = pk % 1024;
        capt = fc_captioned(nodes, regions, fcand, row, page, x0, y0, x1, y1);
        if (rej == 0) && ((conf >= FC_EMIT) || (capt == 1)) {
            if conf < FC_EMIT {
                if kind == fg_unknown() {
                    conf = 400;
                }
            }
            srcs = crate::port::cells_at(fcand, b + CR_SRC);
            link = -1;
            if crate::port::cells_at(fcand, b + CR_KORI) == -1 {
                if level > 0 {
                    link = fc_link(cand, page, crate::port::cells_at(fcand, b + CR_BX), crate::port::cells_at(fcand, b + (CR_BX + 1)), crate::port::cells_at(fcand, b + (CR_BX + 2)), crate::port::cells_at(fcand, b + (CR_BX + 3)));
                }
            }
            if (level == 2) && (crate::port::cells_at(fcand, b + CR_ORG) != 0) {
                as_region_add(cand, page, x0, y0, x1, y1);
            }
            k = row * FD_STRIDE;
            crate::port::cells_set(fd, k, kind);
            crate::port::cells_set(fd, k + 1, conf);
            crate::port::cells_set(fd, k + 2, srcs);
            crate::port::cells_set(fd, k + 3, link);
            crate::port::cells_set(fg, out, row);
            out += 1;
        }
        i += 1;
    }
    crate::port::cells_drop(fg, out);
    rs_figures(nodes, attrs, regions, text, fnodes, fattrs, fregions, fnm, fcand, fg, fd, ab);
    return out - 1;
}
